/* A file's identity as one number: modification time to the nanosecond,
 * mixed with its size.
 *
 * `load` uses it to skip work it has already done. A service that gives every
 * request its own process re-read every table on every request — including
 * requests that never look at them — so a sign-in page cost three times as
 * much with 2000 orders on disk as with 20, despite showing neither. */
static int64_t strata_file_stamp(const char* path) {
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    int64_t t = (int64_t)st.st_mtime * 1000000000LL;
#ifdef __APPLE__
    t += (int64_t)st.st_mtimespec.tv_nsec;
#else
    t += (int64_t)st.st_mtim.tv_nsec;
#endif
    return t ^ ((int64_t)st.st_size << 1);
}

/* Output is line-buffered from the first instruction.
 *
 * A C program whose stdout is not a terminal gets a 4KB block buffer, so a
 * service that prints one line at startup and then serves prints nothing that
 * anyone can see: `docker logs` on the orders service was empty after a
 * sign-in and an order, and would have stayed empty until the process exited.
 * Found by running the container, not by reading the code. */
__attribute__((constructor))
static void __strata_line_buffer_output(void) {
    setvbuf(stdout, NULL, _IOLBF, 0);
    setvbuf(stderr, NULL, _IONBF, 0);
}

/* ── Scratch memory ───────────────────────────────────────────────────────
 *
 * Strata frees nothing. For a batch job that is correct and costs nothing:
 * the program exits and the operating system takes the memory back. For a
 * server or a phone app it is fatal, because the process stays alive and the
 * working set only grows.
 *
 * Tracking every string individually is the expensive answer -- ownership
 * rules, reference counts, cycles. This is the cheap one, and it works here
 * because of a property the language already has: a value stored in a table
 * is COPIED in (strata_dup on insert), so a table never points at a
 * temporary. That makes the line between "must survive" and "may be thrown
 * away" already true, rather than something to be invented.
 *
 * So temporaries -- concatenations, numbers rendered as text, slices, string
 * builders, query result arrays -- come from a bump allocator, and the whole
 * arena is reset at a point the program chooses: after a request, after a
 * frame, never in a batch job. Tables, their indexes and strata_dup keep
 * using malloc and are untouched by a reset.
 *
 * THE RULE, and it is the whole danger: after strata_scratch_reset() every
 * temporary is gone. Anything that must outlive the reset has to be in a
 * table. A reset in the wrong place is a use-after-free, which is why this
 * is never called automatically.
 *
 * Chunks are kept, not freed, so a steady-state server stops calling malloc
 * altogether once it has seen its busiest request. */

typedef struct StrataChunk {
    struct StrataChunk* next;
    size_t cap;
    size_t used;
    char*  data;
} StrataChunk;

static StrataChunk* strata_scratch_head = NULL;
static StrataChunk* strata_scratch_cur  = NULL;

#define STRATA_CHUNK_MIN ((size_t)1 << 20)   /* 1 MiB */

static StrataChunk* strata_chunk_new(size_t need) {
    size_t cap = need > STRATA_CHUNK_MIN ? need : STRATA_CHUNK_MIN;
    StrataChunk* c = (StrataChunk*)malloc(sizeof(StrataChunk));
    if (!c) return NULL;
    c->data = (char*)malloc(cap);
    if (!c->data) { free(c); return NULL; }
    c->cap = cap; c->used = 0; c->next = NULL;
    return c;
}

/* Out of memory in the arena is not recoverable and not worth pretending
 * about: the caller asked for room and there is none. */
static void* strata_scratch_alloc(size_t n) {
    n = (n + 15u) & ~(size_t)15u;            /* keep doubles aligned */
    if (!strata_scratch_cur) {
        strata_scratch_head = strata_chunk_new(n);
        if (!strata_scratch_head) {
            fprintf(stderr, "[strata] out of memory\n");
            exit(70);
        }
        strata_scratch_cur = strata_scratch_head;
    }
    while (strata_scratch_cur->used + n > strata_scratch_cur->cap) {
        if (!strata_scratch_cur->next) {
            StrataChunk* c = strata_chunk_new(n);
            if (!c) { fprintf(stderr, "[strata] out of memory\n"); exit(70); }
            strata_scratch_cur->next = c;
        }
        strata_scratch_cur = strata_scratch_cur->next;
    }
    void* p = strata_scratch_cur->data + strata_scratch_cur->used;
    strata_scratch_cur->used += n;
    return p;
}

static void* strata_scratch_zalloc(size_t n) {
    void* p = strata_scratch_alloc(n);
    memset(p, 0, (n + 15u) & ~(size_t)15u);
    return p;
}

/* ── Rows waiting to be reclaimed ─────────────────────────────────────────
 *
 * `delete` drops a row from its table and used to leave the memory, on the
 * grounds that a list a query returned a moment ago points at the same rows
 * and the language had no way to know. That was right, and it cost about 34
 * bytes per deleted row: a screen rebuilding its rows every frame grew for as
 * long as it ran.
 *
 * The arena changes it. A query result is arena memory, so the moment the
 * arena is thrown away is a moment when nothing can still be pointing at a
 * deleted row. That is the safe point that did not exist before, and it is
 * where deleted rows are freed.
 *
 * Which means the danger is exactly the arena's danger, not a new one:
 * holding a row across a reset is holding a temporary across a reset. */

typedef void (*StrataRowFree)(void*);

typedef struct { void* ptr; StrataRowFree freer; } StrataRetired;

static StrataRetired* strata_retired    = NULL;
static size_t         strata_retired_n  = 0;
static size_t         strata_retired_cap = 0;

void strata_retire(void* row, StrataRowFree freer) {
    if (!row) return;
    if (strata_retired_n == strata_retired_cap) {
        size_t cap = strata_retired_cap ? strata_retired_cap * 2 : 64;
        StrataRetired* g = (StrataRetired*)realloc(strata_retired,
                                                   cap * sizeof(StrataRetired));
        /* Losing the record only means the row is not reclaimed. That is the
         * old behaviour, and it is better than failing the program. */
        if (!g) return;
        strata_retired = g;
        strata_retired_cap = cap;
    }
    strata_retired[strata_retired_n].ptr   = row;
    strata_retired[strata_retired_n].freer = freer;
    strata_retired_n++;
}

static void strata_reclaim_rows(void) {
    for (size_t i = 0; i < strata_retired_n; i++) {
        strata_retired[i].freer(strata_retired[i].ptr);
    }
    strata_retired_n = 0;
}

/* Rows deleted and not yet reclaimed. For a test that wants to prove they
 * are, rather than believe it. */
strata_int strata_retired_rows(void) { return (strata_int)strata_retired_n; }

/* Throw away every temporary made since the last reset. Chunks are kept for
 * reuse, so this is a few pointer writes however much was allocated. */
void strata_scratch_reset(void) {
    /* Rows first: a retired row may be pointed at by a query result in the
     * arena, and both die here together. */
    strata_reclaim_rows();
    StrataChunk* c = strata_scratch_head;
    while (c) { c->used = 0; c = c->next; }
    strata_scratch_cur = strata_scratch_head;
}

/* How much scratch is currently held, in bytes. For a server or a test that
 * wants to prove the number stops growing. */
strata_int strata_scratch_used(void) {
    strata_int total = 0;
    StrataChunk* c = strata_scratch_head;
    while (c) { total += (strata_int)c->used; c = c->next; }
    return total;
}

