/* ── In-memory table runtime ──────────────────────────────────────────────
   Each `database` block gets a fixed-capacity table of row pointers. A query
   allocates a NULL-terminated array of matching rows; `len` counts it. This is
   deliberately the simplest thing that makes the cross-tier contract
   observable end to end — there is no persistence, no index and no
   transaction. */
/* A table's rows used to live in a fixed array of this size. An insert past
 * the end was skipped -- no error, no message, exit status zero -- so a
 * service quietly stopped recording anything once it had four thousand rows,
 * and a load of a larger file dropped the remainder on the floor. A program
 * asked to store five thousand rows held four thousand and ninety-six and
 * said nothing about the other nine hundred and four.
 *
 * Tables grow now. The constant is the FIRST allocation, not the limit. */
#define STRATA_TABLE_CAP 4096

/* Make room for `need` rows, growing by doubling. Returns 0 only when the
 * machine is out of memory. */
static int strata_table_room(void*** rows, strata_int* cap, strata_int need) {
    if (need <= *cap) return 1;
    strata_int want = *cap ? *cap : STRATA_TABLE_CAP;
    while (want < need) {
        if (want > (strata_int)1 << 40) return 0;   /* refuse to overflow */
        want *= 2;
    }
    void** grown = (void**)realloc(*rows, (size_t)want * sizeof(void*));
    if (!grown) return 0;
    *rows = grown;
    *cap = want;
    return 1;
}

/* Out of memory with a row in hand. There is no honest way to carry on: the
 * caller asked for the row to be stored and it is not stored, and returning
 * quietly is the bug this replaced. */
static void strata_table_full(const char* table) {
    fprintf(stderr, "[strata] out of memory storing a row in %s; "
                    "the row was not stored and cannot be\n", table);
    fflush(stderr);
    exit(70);   /* EX_SOFTWARE */
}

/* ── Lists ────────────────────────────────────────────────────────────────
   A list value is a pointer to its first element, with its element COUNT in
   the machine word immediately before it.

   The obvious alternative, NULL-termination, cannot work: 0 is a valid int
   and "" a valid str, so there is no element value free to act as a
   terminator. It was what strata_len assumed, which is why len([1,2,3])
   returned whatever happened to follow the array on the stack.

   strata_int is 8 bytes, so the data pointer stays 8-byte aligned and a
   double or a pointer can sit there. */
static void* strata_list_new(strata_int count, size_t elem_size) {
    strata_int* base = (strata_int*)strata_scratch_zalloc(sizeof(strata_int)
                                              + (size_t)count * elem_size);
    if (!base) return NULL;
    base[0] = count;
    return (void*)(base + 1);
}

/* A query allocates for every row in the table and then reports how many
   actually matched. */
static void strata_list_set_len(void* list, strata_int count) {
    if (list) ((strata_int*)list)[-1] = count;
}

static strata_int strata_len(void* list) {
    if (!list) return 0;
    return ((strata_int*)list)[-1];
}

/* ── Rendering to a string ────────────────────────────────────────────────
   A layout compiles to a function that writes to a FILE*. open_memstream
   gives it a FILE* backed by a growing buffer, so the same generated function
   serves both `render L to "page.html"` and an HTTP response body without
   the layout knowing the difference. */
static strata_str strata_render_end(FILE* out, char** buf) {
    /* open_memstream only publishes the buffer pointer on fclose, so the
       address is taken rather than the value — passing the value hands over a
       NULL captured before the stream was flushed. */
    fclose(out);
    return (*buf) ? *buf : "";
}

/* ── Aggregates ───────────────────────────────────────────────────────────
   sum, avg, min and max over a list of numbers, or over one column projected
   out of a list of rows. The column case walks an array of row pointers and
   reads a field at a known byte offset, which is what lets a single runtime
   function serve every schema.

   Empty input: sum is 0, and avg, min and max are 0 too rather than an error
   or a NaN. A report over a filter that matched nothing should render zeroes,
   not fail. */
#define STRATA_AGG_SUM 0
#define STRATA_AGG_AVG 1
#define STRATA_AGG_MIN 2
#define STRATA_AGG_MAX 3

/* kind: 0 sum, 1 avg, 2 min, 3 max.  elem: 'i' int, 'f' float.
   offset < 0 means the list holds the numbers directly; otherwise it holds
   row pointers and the number is at that byte offset inside each row. */
static double strata_agg(void* list, int kind, char elem, long offset) {
    strata_int n = strata_len(list);
    if (n <= 0 || !list) return 0.0;
    double acc = 0.0, best = 0.0;
    for (strata_int i = 0; i < n; i++) {
        const void* cell;
        if (offset < 0) {
            cell = (const char*)list + (size_t)i * (elem == 'f' ? sizeof(double)
                                                                : sizeof(strata_int));
        } else {
            void* row = ((void**)list)[i];
            if (!row) continue;
            cell = (const char*)row + offset;
        }
        double v = (elem == 'f') ? *(const double*)cell
                                 : (double)*(const strata_int*)cell;
        acc += v;
        if (i == 0) { best = v; }
        if (kind == STRATA_AGG_MIN) { if (v < best) best = v; }
        if (kind == STRATA_AGG_MAX) { if (v > best) best = v; }
    }
    if (kind == STRATA_AGG_SUM) return acc;
    if (kind == STRATA_AGG_AVG) return acc / (double)n;
    return best;
}

/* ── Inference runtime ────────────────────────────────────────────────────
   A model is one dense layer: output = input × W + b, with W laid out
   row-major as cols_in × cols_out followed by cols_out bias terms. That is
   the whole of it — no hidden layers, no activations beyond the identity, no
   training, no accelerator. It is enough for a linear model to run and for
   the E006 shape contract to mean something end to end, and nothing more is
   claimed. */
#define STRATA_MAX_LAYERS 16

/* A model is a stack of dense layers. `dims` holds nlayers+1 widths — the
   input width, then each layer's output width — and `acts` the activation
   applied after each layer: 'r' relu, 's' sigmoid, 'n' none. A model with no
   hidden layers is one layer, so there is a single forward pass here rather
   than a special case. */
typedef struct {
    int rows_in, cols_in, rows_out, cols_out;
    double* weights;
    int nlayers;
    int dims[STRATA_MAX_LAYERS + 1];
    char acts[STRATA_MAX_LAYERS];
} StrataModel;

static double* strata_tensor(strata_int n) {
    double* t = (double*)calloc((size_t)n, sizeof(double));
    return t;
}
static void strata_tensor_set(double* t, strata_int i, strata_float v) { t[i] = v; }
static strata_float strata_tensor_get(double* t, strata_int i) { return t[i]; }

static double strata_activate(double x, char a) {
    if (a == 'r') return x > 0.0 ? x : 0.0;
    if (a == 's') return 1.0 / (1.0 + exp(-x));
    return x;
}

/* Total weights a model needs: for each layer, in*out plus out biases. */
static size_t strata_weight_count(StrataModel* m) {
    size_t n = 0;
    for (int l = 0; l < m->nlayers; l++)
        n += (size_t)m->dims[l] * m->dims[l + 1] + m->dims[l + 1];
    return n;
}

static double* strata_predict(void* model, double* input) {
    StrataModel* m = (StrataModel*)model;
    double* cur = input;
    double* owned = NULL;
    if (!m->weights) {
        /* untrained: zeros, not garbage */
        return (double*)calloc((size_t)m->cols_out, sizeof(double));
    }
    size_t off = 0;
    for (int l = 0; l < m->nlayers; l++) {
        int ci = m->dims[l], co = m->dims[l + 1];
        double* out = (double*)calloc((size_t)co, sizeof(double));
        for (int j = 0; j < co; j++) {
            double acc = m->weights[off + (size_t)ci * co + j];   /* bias */
            for (int i = 0; i < ci; i++)
                acc += cur[i] * m->weights[off + (size_t)i * co + j];
            out[j] = strata_activate(acc, m->acts[l]);
        }
        off += (size_t)ci * co + co;
        if (owned) free(owned);
        owned = out;
        cur = out;
    }
    return cur;
}

/* Weights are plain whitespace-separated numbers, laid out layer by layer:
   for each layer, cols_in*cols_out of them, then cols_out biases. A text
   format keeps the runtime dependency-free and the file inspectable. */
static strata_int strata_model_load(void* model, strata_str path) {
    StrataModel* m = (StrataModel*)model;
    FILE* f = fopen(path, "r");
    if (!f) return 0;
    size_t n = strata_weight_count(m);
    double* w = (double*)calloc(n, sizeof(double));
    size_t got = 0;
    while (got < n && fscanf(f, "%lf", &w[got]) == 1) got++;
    fclose(f);
    if (got < n) {
        fprintf(stderr, "[STRATA MODEL] '%s' holds %zu weights; this model "
                        "needs %zu. Not loading a partial model.\n",
                path, got, n);
        free(w);
        return 0;
    }
    m->weights = w;
    return 1;
}

/* ── Stream context ───────────────────────────────────────────────────────
   The message a `stream` handler is currently processing. There is no
   transport: no broker client, no socket, no scheduler. A host sets this
   before invoking a handler, and it is empty otherwise. Empty is the honest
   default — returning invented traffic would make a handler look like it
   worked when nothing was connected. */
static strata_str __strata_current_message = "";
static strata_str current_message(void) { return __strata_current_message; }
static void strata_set_message(strata_str m) { __strata_current_message = m; }

/* Element-wise tensor addition. Plain scalar loops — the C compiler may
   vectorise them, but Strata emits no SIMD intrinsics of its own. */
static double* strata_tensor_add(double* a, double* b, strata_int n) {
    double* r = (double*)calloc((size_t)n, sizeof(double));
    for (strata_int i = 0; i < n; i++) r[i] = a[i] + b[i];
    return r;
}

/* ── Table persistence ────────────────────────────────────────────────────
   Rows are written as tab-separated text, one per line, with tabs, newlines
   and backslashes escaped in string fields. Text rather than a binary format
   so a table is inspectable with the tools everyone already has, and readable
   by something that is not this compiler.

   There is no schema version, no migration and no locking. A file written by
   one schema and read by another will mis-parse; two writers will corrupt it.
   Suitable for a single process keeping state across restarts. */
static void strata_write_escaped(FILE* f, strata_str s) {
    if (!s) return;
    for (const char* p = s; *p; p++) {
        if (*p == '\\') fputs("\\\\", f);
        else if (*p == '\t') fputs("\\t", f);
        else if (*p == '\n') fputs("\\n", f);
        else fputc(*p, f);
    }
}

/* Reads one escaped field up to a tab or newline. Returns 0 at end of line. */
static int strata_read_field(FILE* f, char* buf, int cap) {
    int n = 0, c;
    while ((c = fgetc(f)) != EOF && c != '\t' && c != '\n') {
        if (c == '\\') {
            int e = fgetc(f);
            if (e == 't') c = '\t';
            else if (e == 'n') c = '\n';
            else if (e == '\\') c = '\\';
            else c = e;
        }
        if (n < cap - 1) buf[n++] = (char)c;
    }
    buf[n] = '\0';
    if (c == EOF && n == 0) return -1;
    return c == '\n' ? 0 : 1;
}
/* ── Schema headers ───────────────────────────────────────────────────────
   A saved table carries a header line naming its columns and their types:

       #strata\tSales\tid:i\tregion:s\tamount:f

   so a file written by one version of a schema can be read by another.
   Columns are matched by name, not by position: one that has since been
   dropped is skipped, one that is new is left at its zero value, and one
   whose type changed is a refusal rather than a silent misread. Without the
   header, adding a column to a `database` block silently corrupted every row
   in every file already on disk. */
#define STRATA_MAX_COLS 64
#define STRATA_NAME_CAP 64

/* Returns the number of columns in the header, -1 if the file has no header
   (written before headers existed), or -2 if the file is empty. */
static int strata_read_header(FILE* f, char names[][STRATA_NAME_CAP],
                              char* types, int cap, char* table_out) {
    char buf[256];
    int n = 0, more;
    if (table_out) table_out[0] = '\0';
    more = strata_read_field(f, buf, 256);
    if (more < 0) return -2;
    if (strcmp(buf, "#strata") != 0) return -1;
    if (more == 0) return 0;
    more = strata_read_field(f, buf, 256);          /* table name */
    if (table_out) {
        strncpy(table_out, buf, STRATA_NAME_CAP - 1);
        table_out[STRATA_NAME_CAP - 1] = '\0';
    }
    while (more > 0 && n < cap) {
        more = strata_read_field(f, buf, 256);
        char* colon = strchr(buf, ':');
        if (colon) {
            *colon = '\0';
            strncpy(names[n], buf, STRATA_NAME_CAP - 1);
            names[n][STRATA_NAME_CAP - 1] = '\0';
            types[n] = colon[1];
            n++;
        }
        if (more == 0) break;
    }
    return n;
}

/* ── Errors that were reported and never looked at ────────────────────────
 *
 * Strata has no exceptions. A load that meets a damaged row refuses the file,
 * says so on stderr and leaves the table empty -- and a caller that does not
 * check the result carries on with no rows and no idea. Four of the bugs
 * found in this project's first fortnight were that same shape: the happy
 * path tested, the error path not. Silence is the problem, not the failure.
 *
 * Halting on the spot would be wrong: a server handling a request should not
 * die because one stored row is bad. So the run is left alone and the
 * accounting moves to the end. An error is recorded; checking it clears it;
 * and a program that reaches its exit with an error still unchecked says so
 * loudly and exits non-zero, where a shell script, a CI job and an operator
 * all notice.
 *
 * A developer who handles errors sees no difference. A developer who ignores
 * them cannot also ignore the exit code. */

/* Errors are kept, not overwritten. One slot meant that two failures before a
 * check left only the second message, so a program that lost a file and then
 * lost a row could only ever tell you about the row. These are fixed buffers
 * rather than allocations: an error path is the worst place to need memory,
 * and they must outlive a scratch_reset() like anything else the program is
 * still holding. Past STRATA_ERR_KEPT the oldest are dropped and the count
 * still rises, because the first failures are usually the interesting ones
 * and a runaway loop should not be able to exhaust anything. */

#define STRATA_ERR_KEPT 16
#define STRATA_ERR_LEN  512

static int   strata_err_pending = 0;
static char  strata_err_msg[STRATA_ERR_LEN];
static char  strata_err_kept[STRATA_ERR_KEPT][STRATA_ERR_LEN];
static int   strata_err_held = 0;
static long long strata_err_count = 0;

static void strata_error_set(const char* fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(strata_err_msg, sizeof strata_err_msg, fmt, ap);
    va_end(ap);
    if (strata_err_held < STRATA_ERR_KEPT) {
        memcpy(strata_err_kept[strata_err_held], strata_err_msg,
               sizeof strata_err_msg);
        strata_err_held++;
    }
    strata_err_pending = 1;
    strata_err_count++;
}

/* Report a failure from Strata code. Until this, only the runtime could say
 * something had gone wrong, so a function that knew it had failed had no way
 * to tell its caller except a return value the caller could ignore in
 * silence. This is not an exception: nothing unwinds, the function still
 * returns, and the caller still decides. What changes is that ignoring it is
 * no longer silent, because an unchecked error is still an exit 65. */
void strata_fail(strata_str message) {
    strata_error_set("%s", message ? message : "");
}

/* One of the errors held, oldest first. Out of range gives "". */
strata_str strata_error_at(strata_int i) {
    if (i < 0 || i >= (strata_int)strata_err_held) { return (char*)""; }
    return strata_err_kept[i];
}

/* How many are held, which is at most STRATA_ERR_KEPT and may be fewer than
 * strata_error_count() reported. */
strata_int strata_errors_held(void) { return (strata_int)strata_err_held; }

/* 1 when something failed and has not been looked at. Reading it does NOT
 * clear it: a program may want to ask twice. clear_error() clears. */
strata_int strata_had_error(void) { return strata_err_pending ? 1 : 0; }

strata_str strata_last_error(void) {
    return strata_err_pending ? strata_err_msg : (char*)"";
}

/* Say that the error has been dealt with. After this the program exits
 * normally, because a handled failure is not a failure. */
void strata_clear_error(void) { strata_err_pending = 0; strata_err_held = 0; }

/* How many errors have been recorded, checked or not. */
strata_int strata_error_count(void) { return (strata_int)strata_err_count; }

static void strata_error_epilogue(void) {
    if (!strata_err_pending) return;
    fflush(stdout);
    fprintf(stderr,
        "\n[strata] this program finished with an error nobody checked:\n"
        "         %s\n"
        "         %lld error(s) were reported during the run. Call\n"
        "         had_error() and clear_error() to handle them, or read the\n"
        "         messages above. Exiting 65 so this is not mistaken for\n"
        "         success.\n", strata_err_msg, strata_err_count);
    fflush(stderr);
    _exit(65);   /* EX_DATAERR */
}

__attribute__((constructor))
static void strata_install_error_epilogue(void) {
    atexit(strata_error_epilogue);
}

static void strata_load_refuse(const char* table, const char* path,
                               const char* why) {
    fprintf(stderr, "[STRATA LOAD] %s: refusing to read '%s' — %s\n",
            table, path, why);
    strata_error_set("%s: refused to read '%s' — %s", table, path, why);
}

/* A number read from a stored row, or a refusal.
 *
 * atoll and strtod answer 0 for text that is not a number at all, so a
 * corrupted digit in a saved file used to become a silent zero -- in a money
 * column, a balance quietly wrong rather than a load that failed. These
 * insist the whole field is consumed, so "12x" and "notanint" are rejected
 * rather than read as 12 and 0. Empty is accepted as zero: a column the
 * writer had nothing for is not corruption. */
static int strata_parse_int(const char* s, strata_int* out) {
    if (!s || !*s) { *out = 0; return 1; }
    errno = 0;
    char* end = NULL;
    long long v = strtoll(s, &end, 10);
    if (errno == ERANGE) return 0;
    if (end == s) return 0;
    while (*end == ' ' || *end == '\t' || *end == '\r') end++;
    if (*end != '\0') return 0;
    *out = (strata_int)v;
    return 1;
}

static int strata_parse_float(const char* s, strata_float* out) {
    if (!s || !*s) { *out = 0.0; return 1; }
    errno = 0;
    char* end = NULL;
    double v = strtod(s, &end);
    if (errno == ERANGE) return 0;
    if (end == s) return 0;
    while (*end == ' ' || *end == '\t' || *end == '\r') end++;
    if (*end != '\0') return 0;
    *out = (strata_float)v;
    return 1;
}

/* A stored value that is not the type its column says it is. */
static void strata_load_bad_value(const char* table, const char* path,
                                  const char* column, const char* value,
                                  strata_int row) {
    fprintf(stderr, "[STRATA LOAD] %s: refusing to read '%s' — row %lld, "
            "column '%s': '%s' is not a number\n",
            table, path, (long long)row, column, value);
    strata_error_set("%s: refused to read '%s' — row %lld, column '%s': "
                     "'%s' is not a number",
                     table, path, (long long)row, column, value);
}

static strata_str strata_dup(const char* s) {
    size_t n = strlen(s); char* r = (char*)malloc(n + 1);
    memcpy(r, s, n + 1); return r;
}

/* ── Test harness ─────────────────────────────────────────────────────────
   A `verify` block compiles to a function; in test mode an entry point runs
   each one and reports. Assertions record a failure rather than terminating,
   so one broken assertion does not hide the rest of the block. */
static int __strata_fail_count = 0;
static int __strata_assert_count = 0;

static void __strata_assert(int cond, const char* expr, int line) {
    __strata_assert_count++;
    if (!cond) {
        __strata_fail_count++;
        fprintf(stderr, "    FAIL  line %d: %s\n", line, expr);
    }
}

/* ── Stream dispatch ──────────────────────────────────────────────────────
   A `stream` block is a handler for a named channel. Messages are queued with
   strata_publish and delivered by strata_run, which drains the queue and
   calls each handler registered for that channel.

   This is a cooperative single-threaded loop, not a fiber scheduler. There
   are no separate stacks, no preemption, no parallelism and no I/O
   integration: a handler runs to completion before the next message is
   delivered, and publishing from inside a handler appends to the same queue.
   It gives `stream` and current_message() real semantics; it does not make
   them concurrent. */
#define STRATA_QUEUE_CAP 4096
#define STRATA_HANDLER_CAP 256

typedef void (*StrataHandler)(strata_str);

static struct { strata_str channel; StrataHandler fn; }
    __strata_handlers[STRATA_HANDLER_CAP];
static int __strata_handler_count = 0;

static struct { strata_str channel; strata_str message; }
    __strata_queue[STRATA_QUEUE_CAP];
static int __strata_q_head = 0, __strata_q_tail = 0;

static void strata_on(strata_str channel, StrataHandler fn) {
    if (__strata_handler_count < STRATA_HANDLER_CAP) {
        __strata_handlers[__strata_handler_count].channel = channel;
        __strata_handlers[__strata_handler_count].fn = fn;
        __strata_handler_count++;
    }
}

static strata_int strata_publish(strata_str channel, strata_str message) {
    int next = (__strata_q_tail + 1) % STRATA_QUEUE_CAP;
    if (next == __strata_q_head) return 0;      /* full: refuse, do not drop silently */
    __strata_queue[__strata_q_tail].channel = channel;
    __strata_queue[__strata_q_tail].message = message;
    __strata_q_tail = next;
    return 1;
}

/* Drains the queue, returning how many messages were delivered. A handler may
   publish; those messages are delivered in the same run. */
static strata_int strata_run(void) {
    strata_int delivered = 0;
    while (__strata_q_head != __strata_q_tail) {
        strata_str ch = __strata_queue[__strata_q_head].channel;
        strata_str msg = __strata_queue[__strata_q_head].message;
        __strata_q_head = (__strata_q_head + 1) % STRATA_QUEUE_CAP;
        for (int i = 0; i < __strata_handler_count; i++) {
            if (strcmp(__strata_handlers[i].channel, ch) == 0) {
                strata_set_message(msg);
                __strata_handlers[i].fn(msg);
                strata_set_message("");
                delivered++;
            }
        }
    }
    return delivered;
}

/* A path that starts with '$' names an environment variable holding the real
 * one. `save Order to "$DATABASE_URL";` is how a service is pointed at its
 * database at deploy time instead of at compile time.
 *
 * Without this the only path a program could give was a string literal, so a
 * Postgres URL -- password included -- would be compiled into the binary and
 * committed to source control. An unset variable is an error the caller
 * reports, not an empty path silently opened. */
static const char* strata_env_path(const char* path) {
    if (!path || path[0] != '$') return path;
    const char* v = getenv(path + 1);
    if (!v || !*v) {
        fprintf(stderr, "[strata] %s is not set; nothing to read or write\n", path + 1);
        return "";
    }
    return v;
}

/* ── A table backed by PostgreSQL ────────────────────────────────────────────
 *
 * Compiled in only when the program links libpq, which happens when it
 * imports `postgres from std`. Every other program is untouched: the branches
 * below vanish at the preprocessor and no libpq dependency is introduced.
 *
 * The rule the language exposes is that the PATH decides the store.
 * `save Order to "orders.tsv"` writes a file; `save Order to
 * "postgres://user:pass@host/db"` writes a table. No new syntax, and a
 * program moves from one to the other by changing a string.
 *
 * Whole-table semantics are kept exactly as the file store has them: a save
 * replaces the table's contents inside one transaction, and a load reads all
 * of it. That is what `save` has always meant in Strata, and changing the
 * meaning depending on the backend would be worse than the cost. It is also
 * the honest limit of this backend — see the note in README. */
#ifdef STRATA_POSTGRES
#include <libpq-fe.h>
#include <unistd.h>   /* getpid, for the per-process connection */

static int strata_pg_is_url(const char* path) {
    return path && (strncmp(path, "postgres://", 11) == 0
                 || strncmp(path, "postgresql://", 13) == 0);
}

/* One connection per URL, per process.
 *
 * Every save and every load used to open its own: a TCP connect, a password
 * exchange and a teardown around a query that takes under a millisecond.
 *
 * The pid is part of the identity, and that is not a detail. A service that
 * forks per request would otherwise have parent and child writing down the
 * same socket, which corrupts the protocol for both. A child finds the pid
 * does not match, drops the inherited handle without speaking on it, and
 * opens its own. */
static PGconn* strata_pg_cached = NULL;
static char*   strata_pg_cached_url = NULL;
static long    strata_pg_cached_pid = 0;

static void* strata_pg_open(const char* url) {
    long pid = (long)getpid();
    if (strata_pg_cached && strata_pg_cached_pid == pid
        && strata_pg_cached_url && strcmp(strata_pg_cached_url, url) == 0) {
        if (PQstatus(strata_pg_cached) == CONNECTION_OK) return (void*)strata_pg_cached;
        PQfinish(strata_pg_cached);
        strata_pg_cached = NULL;
    } else if (strata_pg_cached) {
        /* Inherited across a fork, or pointed at a different database. The
         * inherited one is abandoned rather than closed: closing it would
         * send a termination message down a socket the parent is still
         * using. */
        if (strata_pg_cached_pid == pid) PQfinish(strata_pg_cached);
        strata_pg_cached = NULL;
    }
    free(strata_pg_cached_url);
    strata_pg_cached_url = NULL;
    PGconn* c = PQconnectdb(url);
    if (PQstatus(c) != CONNECTION_OK) {
        fprintf(stderr, "[strata] postgres: %s", PQerrorMessage(c));
        PQfinish(c);
        return NULL;
    }
    /* CREATE TABLE IF NOT EXISTS prints a NOTICE every time the table is
     * already there, which is every save after the first. A service whose
     * normal operation writes a notice to the log teaches people to ignore
     * the log. */
    PQclear(PQexec(c, "SET client_min_messages TO WARNING"));
    strata_pg_cached = c;
    strata_pg_cached_url = strata_dup(url);
    strata_pg_cached_pid = pid;
    return (void*)c;
}

/* Kept open for the next save or load. A connection is closed when the
 * process ends, or when it is found broken on the next use. */
static void strata_pg_close(void* c) { (void)c; }

/* A transaction left open by a failed save would hold its locks until the
 * process exited. Called on every path out of a save that is not a commit. */
static void strata_pg_abort(void* c) {
    if (c) PQclear(PQexec((PGconn*)c, "ROLLBACK"));
}

static int strata_pg_exec(void* c, const char* sql) {
    PGresult* r = PQexec((PGconn*)c, sql);
    ExecStatusType st = PQresultStatus(r);
    int ok = (st == PGRES_COMMAND_OK || st == PGRES_TUPLES_OK);
    if (!ok) fprintf(stderr, "[strata] postgres: %s", PQerrorMessage((PGconn*)c));
    PQclear(r);
    return ok;
}

/* Create the table if it is not there, then empty it, inside a transaction
 * that the caller commits. A reader sees either the old contents or the new
 * ones and never the empty middle. */
static int strata_pg_begin(void* c, const char* table, const char* columns,
                           const char* key, int wipe) {
    char sql[8192];
    if (!strata_pg_exec(c, "BEGIN")) return 0;
    snprintf(sql, sizeof(sql),
             "CREATE TABLE IF NOT EXISTS \"%s\" (%s)", table, columns);
    if (!strata_pg_exec(c, sql)) return 0;
    /* An upsert needs something to conflict on. A table created by an earlier
     * version of this backend has no primary key, so it is added here rather
     * than leaving a database that silently falls back to rewriting every
     * row. Doing it in SQL keeps it one round trip and idempotent. */
    if (key && *key) {
        snprintf(sql, sizeof(sql),
                 "DO $strata$ BEGIN "
                 "IF NOT EXISTS (SELECT 1 FROM pg_constraint "
                 "WHERE conrelid = '\"%s\"'::regclass AND contype = 'p') THEN "
                 "ALTER TABLE \"%s\" ADD PRIMARY KEY (\"%s\"); "
                 "END IF; END $strata$;", table, table, key);
        if (!strata_pg_exec(c, sql)) return 0;
    }
    /* Only when this process has not read the table and so cannot know what
     * else is in it. */
    if (wipe) {
        snprintf(sql, sizeof(sql), "DELETE FROM \"%s\"", table);
        return strata_pg_exec(c, sql);
    }
    return 1;
}

static int strata_pg_insert(void* c, const char* sql, int n, const char** vals) {
    PGresult* r = PQexecParams((PGconn*)c, sql, n, NULL, vals, NULL, NULL, 0);
    int ok = (PQresultStatus(r) == PGRES_COMMAND_OK);
    if (!ok) fprintf(stderr, "[strata] postgres: %s", PQerrorMessage((PGconn*)c));
    PQclear(r);
    return ok;
}

static void* strata_pg_select(void* c, const char* sql) {
    PGresult* r = PQexec((PGconn*)c, sql);
    if (PQresultStatus(r) != PGRES_TUPLES_OK) {
        fprintf(stderr, "[strata] postgres: %s", PQerrorMessage((PGconn*)c));
        PQclear(r);
        return NULL;
    }
    return (void*)r;
}

static strata_int strata_pg_rows(void* r) { return (strata_int)PQntuples((PGresult*)r); }

/* NULL reads back as the column's zero value rather than crashing the
 * service. A row written by something other than Strata is still a row. */
static const char* strata_pg_value(void* r, strata_int row, int col) {
    if (PQgetisnull((PGresult*)r, (int)row, col)) return "";
    return PQgetvalue((PGresult*)r, (int)row, col);
}

static void strata_pg_clear(void* r) { if (r) PQclear((PGresult*)r); }

static const char* strata_pg_int(char* buf, long long v);
static const char* strata_pg_float(char* buf, double v);

/* ── Writing only what changed ────────────────────────────────────────────────
 *
 * A save used to empty the table and write every row back. Change one order
 * in fifty thousand and fifty thousand rows were written. That is what `save`
 * has always meant -- make the store match memory -- and the meaning is kept;
 * what changes is that the store is told only the difference.
 *
 * Each table remembers, per row, its key and a fingerprint of its values as
 * they were at the last load or save against this URL. A row whose
 * fingerprint still matches is not sent. A key that has gone from memory is
 * deleted. Everything else is an upsert.
 *
 * The rule, and its one sharp edge: a save that follows a load writes only
 * the difference. A save with NO prior load from that URL replaces the table
 * wholesale, because a process that has not read the table cannot know what
 * else is in it, and quietly leaving other people's rows behind would be a
 * different meaning of `save` depending on history. */
typedef struct {
    int64_t*  keys;
    uint64_t* hashes;
    strata_int n;
    strata_int cap;
    char*     url;      /* which URL this snapshot describes; NULL = none */
} StrataPgSnap;

static uint64_t strata_pg_hash(int n, const char** vals) {
    /* FNV-1a over the values exactly as they will be sent, so the fingerprint
     * compares what the database will store rather than what is in memory. */
    uint64_t h = 1469598103934665603ULL;
    for (int i = 0; i < n; i++) {
        const char* v = vals[i] ? vals[i] : "";
        for (const char* p = v; *p; p++) {
            h ^= (unsigned char)*p;
            h *= 1099511628211ULL;
        }
        h ^= 0xff;               /* a separator, so ("ab","c") != ("a","bc") */
        h *= 1099511628211ULL;
    }
    return h;
}

static void strata_pg_snap_clear(StrataPgSnap* s) { s->n = 0; }

static int strata_pg_snap_put(StrataPgSnap* s, int64_t key, uint64_t h) {
    if (s->n >= s->cap) {
        strata_int cap = s->cap ? s->cap * 2 : 64;
        int64_t*  k = (int64_t*)realloc(s->keys, (size_t)cap * sizeof(int64_t));
        uint64_t* v = (uint64_t*)realloc(s->hashes, (size_t)cap * sizeof(uint64_t));
        if (!k || !v) { free(k); free(v); s->keys = NULL; s->hashes = NULL;
                        s->cap = 0; s->n = 0; return 0; }
        s->keys = k; s->hashes = v; s->cap = cap;
    }
    s->keys[s->n] = key;
    s->hashes[s->n] = h;
    s->n++;
    return 1;
}

/* Linear, and deliberately so. The alternative is an index rebuilt on every
 * save, and at the table sizes this store is honest about the scan is far
 * cheaper than the one database round trip it saves. */
static int strata_pg_snap_unchanged(StrataPgSnap* s, int64_t key, uint64_t h) {
    for (strata_int i = 0; i < s->n; i++) {
        if (s->keys[i] == key) return s->hashes[i] == h;
    }
    return 0;
}

static int strata_pg_snap_has(StrataPgSnap* s, int64_t key) {
    for (strata_int i = 0; i < s->n; i++) {
        if (s->keys[i] == key) return 1;
    }
    return 0;
}

static void strata_pg_snap_adopt(StrataPgSnap* dst, StrataPgSnap* src, const char* url) {
    free(dst->keys); free(dst->hashes); free(dst->url);
    dst->keys = src->keys; dst->hashes = src->hashes;
    dst->n = src->n; dst->cap = src->cap;
    dst->url = url ? strata_dup(url) : NULL;
    src->keys = NULL; src->hashes = NULL; src->n = 0; src->cap = 0;
}

static int strata_pg_snap_describes(StrataPgSnap* s, const char* url) {
    return s->url && url && strcmp(s->url, url) == 0;
}

/* Rows that were in the table when it was read and are not in memory now. */
static int strata_pg_delete_gone(void* c, const char* sql,
                                 StrataPgSnap* was, StrataPgSnap* now) {
    char buf[48];
    const char* v[1];
    for (strata_int i = 0; i < was->n; i++) {
        if (strata_pg_snap_has(now, was->keys[i])) continue;
        v[0] = strata_pg_int(buf, (long long)was->keys[i]);
        if (!strata_pg_insert(c, sql, 1, v)) return 0;
    }
    return 1;
}

static const char* strata_pg_int(char* buf, long long v) {
    snprintf(buf, 48, "%lld", v);
    return buf;
}

static const char* strata_pg_float(char* buf, double v) {
    snprintf(buf, 48, "%.17g", v);
    return buf;
}
#endif
